values ('guide-1-diagnostic-passerelle-3e-v2', 'Guide 1 V2 - Diagnostic & Passerelle vers la 3e', 1, 'J1', 'CALCUL NUMÉRIQUE : RELATIFS, SIGNES ET PRIORITÉS', 'Calculer sans erreur de signe et respecter les priorités.', 4, 5, '["relatifs_signes", "priorites_operatoires"]'::jsonb, '[{"title": "Règles des signes", "content": "Pour produit/quotient : mêmes signes → positif, signes différents → négatif. Pour une somme, raisonner sur les valeurs et les signes."}, {"title": "Priorités", "content": "Parenthèses, puissances, multiplications/divisions, additions/soustractions."}]'::jsonb, 'PROGRAM_DAY', false, true, '{"source_of_truth": "ÉLAN SCOLAIRE - Guide 1 V2 - Diagnostic & Passerelle vers la 3e", "page_reference": "Pages 4-5", "legacy_learning_program_items_authoritative": false, "official_source": "Guide 1 V2 - Diagnostic & Passerelle vers la 3e"}'::jsonb)
