values ('guide-1-diagnostic-passerelle-3e-v2', 'Guide 1 V2 - Diagnostic & Passerelle vers la 3e', 2, 'J2', 'FRACTIONS ET NOMBRES RATIONNELS', 'Maîtriser les quatre opérations et les calculs enchaînés.', 6, 7, '["fractions"]'::jsonb, '[{"title": "Addition/soustraction", "content": "Mettre au même dénominateur avant d’additionner ou soustraire."}, {"title": "Multiplication/division", "content": "Simplifier si possible ; diviser par une fraction revient à multiplier par son inverse."}]'::jsonb, 'PROGRAM_DAY', false, true, '{"source_of_truth": "ÉLAN SCOLAIRE - Guide 1 V2 - Diagnostic & Passerelle vers la 3e", "page_reference": "Pages 6-7", "legacy_learning_program_items_authoritative": false, "official_source": "Guide 1 V2 - Diagnostic & Passerelle vers la 3e"}'::jsonb)
