values ('guide-1-diagnostic-passerelle-3e-v2', 'Guide 1 V2 - Diagnostic & Passerelle vers la 3e', 3, 'J3', 'PUISSANCES ET CALCULS NUMÉRIQUES', 'Utiliser correctement les règles sur les puissances.', 8, 9, '["puissances"]'::jsonb, '[{"title": "Même base", "content": "a^m×a^n=a^(m+n) et a^m÷a^n=a^(m-n), a≠0."}, {"title": "Puissance d’une puissance", "content": "(a^m)^n=a^(mn). Les parenthèses changent parfois le signe."}]'::jsonb, 'PROGRAM_DAY', false, true, '{"source_of_truth": "ÉLAN SCOLAIRE - Guide 1 V2 - Diagnostic & Passerelle vers la 3e", "page_reference": "Pages 8-9", "legacy_learning_program_items_authoritative": false, "official_source": "Guide 1 V2 - Diagnostic & Passerelle vers la 3e"}'::jsonb)
