values ('guide-1-diagnostic-passerelle-3e-v2', 'Guide 1 V2 - Diagnostic & Passerelle vers la 3e', 5, 'J5', 'DÉVELOPPEMENT ET IDENTITÉS REMARQUABLES', 'Développer des produits et utiliser les trois identités remarquables.', 12, 13, '["developpement", "identites_remarquables"]'::jsonb, '[{"title": "Distributivité", "content": "a(b+c)=ab+ac et (a+b)(c+d)=ac+ad+bc+bd."}, {"title": "Identités remarquables", "content": "(a+b)²=a²+2ab+b² ; (a-b)²=a²-2ab+b² ; (a-b)(a+b)=a²-b²."}]'::jsonb, 'PROGRAM_DAY', false, true, '{"source_of_truth": "ÉLAN SCOLAIRE - Guide 1 V2 - Diagnostic & Passerelle vers la 3e", "page_reference": "Pages 12-13", "legacy_learning_program_items_authoritative": false, "official_source": "Guide 1 V2 - Diagnostic & Passerelle vers la 3e"}'::jsonb)
