values ('guide-1-diagnostic-passerelle-3e-v2', 'Guide 1 V2 - Diagnostic & Passerelle vers la 3e', 7, 'J7', 'ÉQUATIONS, INÉQUATIONS ET PROBLÈMES', 'Résoudre et traduire des problèmes en relations algébriques.', 16, 17, '["equations", "inequations"]'::jsonb, '[{"title": "Équations", "content": "Faire la même opération dans les deux membres puis vérifier."}, {"title": "Inéquations", "content": "Si on multiplie ou divise par un nombre négatif, on inverse le sens de l’inégalité."}]'::jsonb, 'PROGRAM_DAY', false, true, '{"source_of_truth": "ÉLAN SCOLAIRE - Guide 1 V2 - Diagnostic & Passerelle vers la 3e", "page_reference": "Pages 16-17", "legacy_learning_program_items_authoritative": false, "official_source": "Guide 1 V2 - Diagnostic & Passerelle vers la 3e"}'::jsonb)
